export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    let path = url.pathname;

    // Normalize trailing slash
    if (path.length > 1 && path.endsWith('/')) {
      path = path.slice(0, -1);
    }

    // Check routes
    const asset = ASSET_ROUTES[path] || ASSET_ROUTES[path + '.html'];

    if (asset) {
      return new Response(asset.content, {
        status: 200,
        headers: {
          'Content-Type': asset.type,
          'Cache-Control': 'public, max-age=3600, s-maxage=86400, stale-while-revalidate=604800',
          'X-Powered-By': 'agy_auto_site / Cloudflare Workers',
          'Access-Control-Allow-Origin': '*'
        }
      });
    }

    // 404 Fallback
    const notFoundHtml = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8"><title>Page Not Found | 404</title>
  <script src="https://cdn.tailwindcss.com"></script>
</head>
<body class="bg-slate-900 text-white min-h-screen flex flex-col items-center justify-center p-4">
  <div class="text-center max-w-md">
    <h1 class="text-6xl font-black text-indigo-500 mb-4">404</h1>
    <h2 class="text-2xl font-bold mb-2">Page Not Found</h2>
    <p class="text-slate-400 mb-6">The requested page does not exist or has been relocated.</p>
    <a href="/" class="px-6 py-3 bg-indigo-600 hover:bg-indigo-700 rounded-xl font-semibold transition">Back to Homepage</a>
  </div>
</body>
</html>`;

    return new Response(notFoundHtml, {
      status: 404,
      headers: {
        'Content-Type': 'text/html; charset=utf-8'
      }
    });
  }
};
